sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Reschedule count cannot exceed 2
    var reschedCount = parseInt(current.reschedule_count, 10) || 0;
    if (reschedCount > 2) {
        current.setAbortAction(true);
        gs.addErrorMessage('Appointment cannot be rescheduled more than 2 times.');
        return;
    }

    // 2. A patient cancel or reschedule is rejected less than 4 hours before the slot
    var isCancelling = (current.status == '7' && previous.status != '7');
    var isRescheduling = (current.status == '9' && previous.status != '9') ||
                         (current.start_time.changes() && previous.start_time) ||
                         (current.reschedule_count.changes() && current.operation() == 'update');

    // Only apply the 4-hour rule to Patient-initiated actions
    var cancelledByPatient = (current.cancelled_by == '1' || current.cancelled_by == '');

    if ((isCancelling && cancelledByPatient) || isRescheduling) {
        var slotStartTimeStr = previous.start_time.nil() ? current.start_time : previous.start_time;
        if (slotStartTimeStr) {
            var slotStart = new GlideDateTime(slotStartTimeStr);
            var now = new GlideDateTime();

            var diffMs = slotStart.getNumericValue() - now.getNumericValue();
            var fourHoursMs = 4 * 60 * 60 * 1000; 

            if (diffMs < fourHoursMs) {
                current.setAbortAction(true);
                if (isCancelling) {
                    gs.addErrorMessage('Appointments cannot be cancelled less than 4 hours before the scheduled slot.');
                } else {
                    gs.addErrorMessage('Appointments cannot be rescheduled less than 4 hours before the scheduled slot.');
                }
                return;
            }
        }
    }

})(current, previous);
